WITH gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) > INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM sessions), sessions_sessions AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT CASE WHEN session_id >= 7 THEN 'HIGH' ELSE 'LOW' END AS session_id_tier, session_id, ROUND(AVG(session_id), 2) AS avg_session_id, MIN(started_at) AS first_started_at, DENSE_RANK() OVER (PARTITION BY CASE WHEN session_id >= 7 THEN 'HIGH' ELSE 'LOW' END ORDER BY ROUND(AVG(session_id), 2) DESC) AS avg_session_id_dense_rank FROM sessions_sessions GROUP BY CASE WHEN session_id >= 7 THEN 'HIGH' ELSE 'LOW' END, session_id;
